export type Class1PreviewLanguage = 'en' | 'hi' | 'mr'
export type Class1PreviewScaffold = 'MODEL' | 'GUIDE' | 'PRACTISE' | 'EXTEND'

/** Never use the transcript as an IQ or pronunciation measurement. The staff
 * explicitly chooses the rehearsal mode; real voice evidence uses the backend.
 */
export function class1PreviewCoachLine(chapter: string, language: Class1PreviewLanguage, mode: Class1PreviewScaffold): string {
  const example = CLASS1_DRAFT_MODELS[chapter]
  if (!example) throw new Error(`Missing staff rehearsal phrase for Balbharati ${chapter}`)

  if (language === 'hi') {
    if (mode === 'MODEL') return `सुनो: ${example}। अब मेरे साथ बोलो।`
    if (mode === 'GUIDE') return `कोई बात नहीं। धीरे बोलें: ${example}।`
    if (mode === 'PRACTISE') return `अच्छी कोशिश! फिर इंग्लिश में बोलो: ${example}।`
    return `बहुत अच्छा प्रयास! अब खुद से कहो: ${example}।`
  }
  if (language === 'mr') {
    if (mode === 'MODEL') return `ऐक: ${example}। आता माझ्यासोबत म्हण।`
    if (mode === 'GUIDE') return `काही हरकत नाही। हळू म्हण: ${example}।`
    if (mode === 'PRACTISE') return `छान प्रयत्न! पुन्हा इंग्रजीत म्हण: ${example}।`
    return `मस्त प्रयत्न! आता स्वतः म्हण: ${example}।`
  }
  if (mode === 'MODEL') return `Listen first: ${example}. Say it with me.`
  if (mode === 'GUIDE') return `No worries. Slowly now: ${example}. Your turn.`
  if (mode === 'PRACTISE') return `Nice effort! Let's say: ${example}, one more time.`
  return `Great effort! Now try saying: ${example}, by yourself.`
}
